// Procedural PBR material library. NO binary assets (house rule) — every albedo,
// normal, roughness and AO map is synthesized here from seeded noise.
//
// OWNED BY: materials/texture agent. Signature is fixed by main.js.

import * as THREE from 'three';
import { fbm2, ridge2, worley2, hash2 } from '../core/rng.js';
import { clamp01, lerp, smoothstep } from '../core/mathx.js';

const TEX = 1024;

function canvas2d(size = TEX) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return [c, c.getContext('2d', { willReadFrequently: true })];
}

function toTexture(canvas, { srgb = false, aniso = 16, repeat = 1 } = {}) {
  const t = new THREE.CanvasTexture(canvas);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.anisotropy = aniso;
  t.repeat.set(repeat, repeat);
  t.needsUpdate = true;
  return t;
}

// Height -> tangent-space normal via central differences. Sobel would be smoother
// but central-diff keeps hard edges (panel seams, tile grout) crisp.
function heightToNormal(height, size, strength = 2.2) {
  const [c, ctx] = canvas2d(size);
  const img = ctx.createImageData(size, size);
  const at = (x, y) => height[((y + size) % size) * size + ((x + size) % size)];
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = (at(x + 1, y) - at(x - 1, y)) * strength;
      const dy = (at(x, y + 1) - at(x, y - 1)) * strength;
      const len = Math.hypot(dx, dy, 1);
      const i = (y * size + x) * 4;
      img.data[i] = ((-dx / len) * 0.5 + 0.5) * 255;
      img.data[i + 1] = ((-dy / len) * 0.5 + 0.5) * 255;
      img.data[i + 2] = (1 / len) * 0.5 * 255 + 127.5;
      img.data[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return c;
}

function writeGray(values, size) {
  const [c, ctx] = canvas2d(size);
  const img = ctx.createImageData(size, size);
  for (let i = 0; i < values.length; i++) {
    const v = clamp01(values[i]) * 255;
    img.data[i * 4] = img.data[i * 4 + 1] = img.data[i * 4 + 2] = v;
    img.data[i * 4 + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  return c;
}

function writeColor(fn, size) {
  const [c, ctx] = canvas2d(size);
  const img = ctx.createImageData(size, size);
  const rgb = [0, 0, 0];
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      fn(x / size, y / size, x, y, rgb);
      const i = (y * size + x) * 4;
      img.data[i] = clamp01(rgb[0]) * 255;
      img.data[i + 1] = clamp01(rgb[1]) * 255;
      img.data[i + 2] = clamp01(rgb[2]) * 255;
      img.data[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return c;
}

// ---- concrete ------------------------------------------------------------
function concrete(seed, size = TEX) {
  const h = new Float32Array(size * size);
  const rough = new Float32Array(size * size);
  const s = 8 / size;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = y * size + x;
      const grain = fbm2(x * s, y * s, { octaves: 6, seed, period: 8 });
      const agg = worley2(x * s * 3, y * s * 3, seed + 11, 24);   // aggregate pebbles
      const crack = ridge2(x * s * 0.6, y * s * 0.6, { octaves: 4, seed: seed + 5, period: 5 });
      const pit = smoothstep(0.72, 0.95, fbm2(x * s * 6, y * s * 6, { octaves: 3, seed: seed + 21, period: 48 }));
      h[i] = grain * 0.55 + agg * 0.25 - pit * 0.5 - smoothstep(0.55, 0.9, crack) * 0.6;
      rough[i] = 0.72 + grain * 0.18 + pit * 0.12;
    }
  }
  const albedo = writeColor((u, v, x, y, out) => {
    const i = y * size + x;
    const n = h[i] * 0.5 + 0.5;
    const stain = fbm2(x * s * 0.35, y * s * 0.35, { octaves: 4, seed: seed + 77, period: 3 });
    const base = lerp(0.30, 0.44, n) * lerp(0.82, 1.06, stain);
    out[0] = base * 1.02; out[1] = base * 1.0; out[2] = base * 0.95;
  }, size);
  return {
    map: toTexture(albedo, { srgb: true }),
    normalMap: toTexture(heightToNormal(h, size, 1.9)),
    roughnessMap: toTexture(writeGray(rough, size)),
  };
}

// ---- painted / scuffed metal panel ---------------------------------------
function metalPanel(seed, size = TEX) {
  const h = new Float32Array(size * size);
  const rough = new Float32Array(size * size);
  const metal = new Float32Array(size * size);
  const s = 6 / size;
  const PANEL = 4;                       // panels per tile
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = y * size + x;
      const u = x / size * PANEL, v = y / size * PANEL;
      const seamU = Math.abs((u % 1) - 0.5), seamV = Math.abs((v % 1) - 0.5);
      const seam = smoothstep(0.5, 0.46, Math.min(seamU, seamV));  // recessed groove
      const brushed = fbm2(x * s * 0.35, y * s * 14, { octaves: 3, seed, period: 4 });  // anisotropic streaks
      // Paint chips off at panel edges first — worley threshold biased by seam proximity.
      const chip = smoothstep(0.62 - seam * 0.25, 0.68, worley2(x * s * 5, y * s * 5, seed + 3, 40));
      h[i] = -seam * 0.9 + brushed * 0.06 - chip * 0.15;
      rough[i] = lerp(0.42, 0.66, brushed) + chip * 0.22 + seam * 0.1;
      metal[i] = chip > 0.5 ? 1 : 0.05;   // exposed steel under chipped paint
    }
  }
  const albedo = writeColor((u, v, x, y, out) => {
    const i = y * size + x;
    const chipped = metal[i] > 0.5;
    const t = fbm2(x * s * 2, y * s * 2, { octaves: 3, seed: seed + 9, period: 12 });
    if (chipped) { const g = lerp(0.44, 0.56, t); out[0] = g; out[1] = g * 1.0; out[2] = g * 1.02; }
    else { out[0] = lerp(0.16, 0.21, t); out[1] = lerp(0.19, 0.245, t); out[2] = lerp(0.205, 0.26, t); }
  }, size);
  return {
    map: toTexture(albedo, { srgb: true }),
    normalMap: toTexture(heightToNormal(h, size, 2.6)),
    roughnessMap: toTexture(writeGray(rough, size)),
    metalnessMap: toTexture(writeGray(metal, size)),
  };
}

// ---- asphalt / road ------------------------------------------------------
function asphalt(seed, size = TEX) {
  const h = new Float32Array(size * size);
  const rough = new Float32Array(size * size);
  const s = 10 / size;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const i = y * size + x;
      const g = worley2(x * s * 6, y * s * 6, seed, 60);
      const fine = fbm2(x * s * 3, y * s * 3, { octaves: 5, seed: seed + 4, period: 30 });
      h[i] = g * 0.6 + fine * 0.4;
      rough[i] = 0.78 + fine * 0.16;
    }
  }
  const albedo = writeColor((u, v, x, y, out) => {
    const i = y * size + x;
    const n = h[i];
    const c = lerp(0.055, 0.12, n) * lerp(0.9, 1.15, fbm2(x * s * 0.4, y * s * 0.4, { octaves: 3, seed: seed + 31, period: 4 }));
    out[0] = c; out[1] = c * 1.01; out[2] = c * 1.05;
  }, size);
  return {
    map: toTexture(albedo, { srgb: true }),
    normalMap: toTexture(heightToNormal(h, size, 1.4)),
    roughnessMap: toTexture(writeGray(rough, size)),
  };
}

// ---- procedural sky -> IBL ----------------------------------------------
// Physically-shaped gradient (Rayleigh-ish horizon warm, zenith cool) run through
// PMREM. This one map does most of the "AAA" heavy lifting: without real ambient
// specular, PBR surfaces read as flat plastic no matter how good the albedo is.
function buildEnvironment(renderer, sunDir) {
  const s = new THREE.Scene();
  const size = 512;
  const [c, ctx] = canvas2d(size);
  const img = ctx.createImageData(size, size);
  for (let y = 0; y < size; y++) {
    const v = y / size;
    const el = 1 - v;                                  // 1 = zenith
    for (let x = 0; x < size; x++) {
      const i = (y * size + x) * 4;
      const horizon = Math.pow(1 - el, 3.2);
      const r = lerp(0.115, 0.62, horizon) + Math.pow(1 - el, 12) * 0.5;
      const g = lerp(0.19, 0.55, horizon) + Math.pow(1 - el, 12) * 0.32;
      const b = lerp(0.42, 0.60, horizon) + Math.pow(1 - el, 12) * 0.18;
      const ground = el < 0.5 ? smoothstep(0.5, 0.42, el) : 0;
      img.data[i] = clamp01(lerp(r, 0.13, ground)) * 255;
      img.data[i + 1] = clamp01(lerp(g, 0.125, ground)) * 255;
      img.data[i + 2] = clamp01(lerp(b, 0.12, ground)) * 255;
      img.data[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  const skyTex = new THREE.CanvasTexture(c);
  skyTex.mapping = THREE.EquirectangularReflectionMapping;
  skyTex.colorSpace = THREE.SRGBColorSpace;
  skyTex.needsUpdate = true;

  const pmrem = new THREE.PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();
  const env = pmrem.fromEquirectangular(skyTex).texture;
  pmrem.dispose();
  skyTex.dispose();
  return { env, skyCanvas: c };
}

export async function createMaterialLibrary({ renderer, rng }) {
  const seed = Math.floor(rng() * 1e9);
  const sunDir = new THREE.Vector3(-0.42, 0.78, 0.46).normalize();
  const { env, skyCanvas } = buildEnvironment(renderer, sunDir);

  const defs = {
    concrete: { tex: concrete(seed + 1), p: { roughness: 1, metalness: 0, repeat: 3 } },
    concreteWall: { tex: concrete(seed + 2), p: { roughness: 1, metalness: 0, repeat: 2 } },
    metal: { tex: metalPanel(seed + 3), p: { roughness: 1, metalness: 1, repeat: 2 } },
    asphalt: { tex: asphalt(seed + 4), p: { roughness: 1, metalness: 0, repeat: 6 } },
  };

  const cache = new Map();
  for (const [name, d] of Object.entries(defs)) {
    const m = new THREE.MeshStandardMaterial({
      map: d.tex.map,
      normalMap: d.tex.normalMap,
      roughnessMap: d.tex.roughnessMap,
      metalnessMap: d.tex.metalnessMap ?? null,
      roughness: d.p.roughness,
      metalness: d.p.metalness,
      envMapIntensity: 1.0,
      normalScale: new THREE.Vector2(1, 1),
      dithering: true,
    });
    for (const t of Object.values(d.tex)) t.repeat?.set(d.p.repeat, d.p.repeat);
    cache.set(name, m);
  }

  return {
    env, sunDir, skyCanvas,
    get(name) {
      const m = cache.get(name);
      if (!m) throw new Error(`[materials] unknown material "${name}"`);
      return m;
    },
    list() { return [...cache.keys()]; },
    dispose() {
      for (const m of cache.values()) {
        for (const k of ['map', 'normalMap', 'roughnessMap', 'metalnessMap']) m[k]?.dispose();
        m.dispose();
      }
      env.dispose();
      cache.clear();
    },
  };
}
