// Post-processing chain. Baseline implementation — OWNED BY: render agent, whose
// job is to extend this to motion-vector TAA, SSR, and per-frame jitter.
//
// Order matters: AO must apply to lit-but-pre-tonemap HDR, bloom reads HDR
// highlights, tonemap+grade is terminal, AA resolves last.

import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
import { GTAOPass } from 'three/addons/postprocessing/GTAOPass.js';
import { FXAAShader } from 'three/addons/shaders/FXAAShader.js';

// Terminal grade: filmic contrast S-curve, subtle blue-shadow / warm-highlight
// split-tone, vignette, chromatic aberration, and film grain. Grain is the cheap
// trick that most convincingly kills the "clean CG plastic" look.
const GradeShader = {
  uniforms: {
    tDiffuse: { value: null },
    uTime: { value: 0 },
    uVignette: { value: 0.42 },
    uGrain: { value: 0.035 },
    uAberration: { value: 0.0016 },
    uContrast: { value: 1.06 },
    uSaturation: { value: 1.04 },
    uLift: { value: new THREE.Vector3(0.005, 0.008, 0.018) },
    uGain: { value: new THREE.Vector3(1.02, 1.0, 0.97) },
  },
  vertexShader: /* glsl */`
    varying vec2 vUv;
    void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
  `,
  fragmentShader: /* glsl */`
    uniform sampler2D tDiffuse;
    uniform float uTime, uVignette, uGrain, uAberration, uContrast, uSaturation;
    uniform vec3 uLift, uGain;
    varying vec2 vUv;

    float hash(vec2 p){ return fract(sin(dot(p, vec2(127.1,311.7))) * 43758.5453); }

    void main(){
      vec2 d = vUv - 0.5;
      float r2 = dot(d,d);
      // Aberration scales with r^2 — matches real lens behaviour (none at center).
      vec2 off = d * uAberration * r2 * 4.0;
      vec3 c;
      c.r = texture2D(tDiffuse, vUv + off).r;
      c.g = texture2D(tDiffuse, vUv).g;
      c.b = texture2D(tDiffuse, vUv - off).b;

      c = c * uGain + uLift;
      c = (c - 0.5) * uContrast + 0.5;
      float l = dot(c, vec3(0.2126, 0.7152, 0.0722));
      c = mix(vec3(l), c, uSaturation);

      c *= 1.0 - uVignette * pow(r2 * 2.0, 1.35);

      float g = hash(vUv * 1024.0 + fract(uTime) * 91.7) - 0.5;
      c += g * uGrain * (1.0 - l * 0.7);   // grain strongest in shadows, like real film

      gl_FragColor = vec4(max(c, 0.0), 1.0);
    }
  `,
};

export function createPipeline({ rc, scene, quality }) {
  const { renderer, camera } = rc;
  const size = rc.size();

  const composer = new EffectComposer(renderer, rc.hdrTarget(size.x, size.y));
  composer.setPixelRatio(renderer.getPixelRatio());

  const renderPass = new RenderPass(scene, camera);
  composer.addPass(renderPass);

  let gtao = null;
  if (quality.ssao) {
    gtao = new GTAOPass(scene, camera, size.x, size.y);
    gtao.output = GTAOPass.OUTPUT.Default;
    gtao.updateGtaoMaterial({
      radius: 0.42, distanceExponent: 1.6, thickness: 1.0,
      scale: 1.0, samples: 16, screenSpaceRadius: false,
    });
    composer.addPass(gtao);
  }

  const bloom = new UnrealBloomPass(new THREE.Vector2(size.x, size.y), 0.34, 0.72, 0.92);
  composer.addPass(bloom);

  const grade = new ShaderPass(GradeShader);
  composer.addPass(grade);

  composer.addPass(new OutputPass());

  const fxaa = new ShaderPass(FXAAShader);
  const setFxaa = (w, h) => {
    const pr = renderer.getPixelRatio();
    fxaa.material.uniforms.resolution.value.set(1 / (w * pr), 1 / (h * pr));
  };
  setFxaa(size.x, size.y);
  composer.addPass(fxaa);

  let t = 0;
  return {
    composer,
    params: { bloom, grade: grade.material.uniforms, gtao },
    render(alpha) {
      t += 1 / 60;
      grade.material.uniforms.uTime.value = t;
      composer.render();
    },
    resize(w, h) {
      composer.setSize(w, h);
      composer.setPixelRatio(renderer.getPixelRatio());
      gtao?.setSize(w, h);
      bloom.setSize(w, h);
      setFxaa(w, h);
    },
    dispose() { composer.dispose(); },
  };
}
