// STUB — OWNED BY: HUD agent. Must deliver: dynamic crosshair driven by the real
// spread value, hitmarkers, damage direction indicators, ammo counter, compass.
// Canvas2D overlay — never per-frame DOM writes.

export function createHUD({ root, bus }) {
  const el = document.createElement('div');
  el.style.cssText = 'position:absolute;left:10px;top:8px;font:11px ui-monospace,monospace;color:#7d8894';
  root.appendChild(el);
  let acc = 0;
  return {
    step(dt, ctx) {
      acc += dt;
      if (acc < 0.25) return;           // throttle DOM writes to 4 Hz
      acc = 0;
      const s = ctx.stats;
      if (s) el.textContent = `${s.fps.toFixed(0)} fps · ${s.frameMs.toFixed(1)} ms`;
    },
    dispose() { el.remove(); },
  };
}
