// Level geometry + collision. Baseline blockout — OWNED BY: level/environment agent.
//
// Collision is AABB-vs-capsule against a static brush list. Brushes are authored
// as the SAME data that builds the render mesh, so visual and collision geometry
// can never desync (the classic source of "shot through a wall" bugs).

import * as THREE from 'three';

export function createLevel({ scene, rng, mats }) {
  const root = new THREE.Group();
  root.name = 'level';
  scene.add(root);

  const brushes = [];   // { min:Vec3, max:Vec3 }

  // box(): one call authors render mesh + collider together.
  const box = (mat, x, y, z, w, h, d, { collide = true } = {}) => {
    const g = new THREE.BoxGeometry(w, h, d);
    const m = new THREE.Mesh(g, mats.get(mat));
    m.position.set(x, y + h / 2, z);
    m.castShadow = m.receiveShadow = true;
    root.add(m);
    if (collide) {
      brushes.push({
        min: new THREE.Vector3(x - w / 2, y, z - d / 2),
        max: new THREE.Vector3(x + w / 2, y + h, z + d / 2),
      });
    }
    return m;
  };

  // ---- ground ------------------------------------------------------------
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(240, 240, 1, 1), mats.get('asphalt'));
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  root.add(ground);
  brushes.push({ min: new THREE.Vector3(-120, -2, -120), max: new THREE.Vector3(120, 0, 120) });

  // ---- courtyard blockout -----------------------------------------------
  const W = 'concreteWall';
  box(W, 0, 0, -22, 44, 7, 1.2);
  box(W, -22, 0, 0, 1.2, 7, 44);
  box(W, 22, 0, 0, 1.2, 7, 44);
  box(W, 0, 0, 22, 44, 7, 1.2);

  // interior cover — staggered so no straight sightline crosses the whole space
  box('concrete', -8, 0, -6, 5, 1.15, 2.4);
  box('concrete', 7, 0, 2, 2.4, 1.15, 6);
  box('concrete', -3, 0, 10, 6, 1.9, 2.2);
  box('metal', 12, 0, -12, 3.2, 2.6, 3.2);
  box('metal', -14, 0, 12, 3.6, 2.2, 2.8);
  box('concrete', 2, 0, -14, 8, 3.4, 1.4);

  // elevated walkway + supports
  box('metal', -18, 3.2, -10, 8, 0.4, 3);
  box('metal', -21, 0, -10, 0.5, 3.2, 0.5);
  box('metal', -15, 0, -10, 0.5, 3.2, 0.5);

  // Lighting + sky are NOT owned here — see render/lighting.js and render/sky.js.
  // Atmospheric fog is a world property though, so it stays.
  scene.fog = new THREE.FogExp2(0x93a6bd, 0.0062);

  // ---- collision ---------------------------------------------------------
  // Vertical capsule vs AABB, resolved on the axis of least penetration.
  // Returns a corrected position + ground flag.
  const _p = new THREE.Vector3();
  function collide(pos, radius, height) {
    _p.copy(pos);
    let grounded = false;
    for (let iter = 0; iter < 3; iter++) {           // few passes settle corner cases
      for (const b of brushes) {
        const cx = Math.max(b.min.x, Math.min(_p.x, b.max.x));
        const cz = Math.max(b.min.z, Math.min(_p.z, b.max.z));
        const feet = _p.y, head = _p.y + height;
        if (head < b.min.y || feet > b.max.y) continue;

        const dx = _p.x - cx, dz = _p.z - cz;
        const d2 = dx * dx + dz * dz;
        if (d2 > radius * radius) continue;

        const overlapY = Math.min(head, b.max.y) - Math.max(feet, b.min.y);
        const d = Math.sqrt(d2) || 1e-6;
        const pushXZ = radius - d;

        // Prefer standing on top when the vertical overlap is the shallower fix.
        if (overlapY < pushXZ && feet < b.max.y && feet > b.max.y - 0.55) {
          _p.y = b.max.y; grounded = true;
        } else if (d2 > 1e-9) {
          _p.x += (dx / d) * pushXZ;
          _p.z += (dz / d) * pushXZ;
        } else {
          _p.x += radius;                            // dead-center degenerate case
        }
      }
    }
    if (_p.y <= 0) { _p.y = 0; grounded = true; }
    return { pos: _p, grounded };
  }

  // Ray vs brush AABBs (slab test). Used by ballistics + AI line-of-sight.
  function raycast(origin, dir, maxDist = 200) {
    let best = maxDist, hitN = null;
    for (const b of brushes) {
      let t0 = 0, t1 = best, n = null;
      for (const ax of ['x', 'y', 'z']) {
        const inv = 1 / (dir[ax] || 1e-9);
        let ta = (b.min[ax] - origin[ax]) * inv;
        let tb = (b.max[ax] - origin[ax]) * inv;
        let sign = -Math.sign(dir[ax]);
        if (ta > tb) { const t = ta; ta = tb; tb = t; sign = -sign; }
        if (ta > t0) { t0 = ta; n = { x: 0, y: 0, z: 0 }; n[ax] = sign; }
        if (tb < t1) t1 = tb;
        if (t0 > t1) { t0 = Infinity; break; }
      }
      if (t0 < best && t0 > 0.001) { best = t0; hitN = n; }
    }
    return hitN ? { dist: best, normal: new THREE.Vector3(hitN.x, hitN.y, hitN.z) } : null;
  }

  return {
    root, brushes, collide, raycast,
    spawns: [new THREE.Vector3(0, 0, 16)],
    // Named camera poses for the headless critic harness.
    poses: {
      hero:     { pos: new THREE.Vector3(6, 0, 15), yaw: -0.42, pitch: -0.04 },
      corridor: { pos: new THREE.Vector3(-17, 0, 6), yaw: 1.15, pitch: 0.0 },
      ads:      { pos: new THREE.Vector3(0, 0, 12), yaw: 0.1, pitch: -0.02, ads: true },
      overlook: { pos: new THREE.Vector3(-18, 3.2, -10), yaw: 2.0, pitch: -0.12 },
    },
    step() {},
    dispose() {
      root.traverse((o) => { o.geometry?.dispose?.(); });
      scene.remove(root);
    },
  };
}
